// Расчёт показателей по каждому товару
const items = $input.all();

return items.map(item => {
  const d = item.json;

  // Динамика продаж: текущая неделя vs предыдущая
  const salesNow   = d.revenue_current  ?? d.revenue  ?? 0;
  const salesPrev  = d.revenue_previous ?? salesNow;
  const salesDelta = salesPrev > 0 ? ((salesNow - salesPrev) / salesPrev) * 100 : 0;

  const ordersNow   = d.ordered_units_current  ?? d.ordered_units  ?? 0;
  const ordersPrev  = d.ordered_units_previous ?? ordersNow;
  const ordersDelta = ordersPrev > 0 ? ((ordersNow - ordersPrev) / ordersPrev) * 100 : 0;

  // Конверсия
  const views    = d.hits_view    ?? 1;
  const sessions = d.session_view ?? 1;
  const toCart   = d.hits_tocart  ?? 0;
  const ctrToCart    = views    > 0 ? (toCart / views) * 100 : 0;
  const convToCart   = sessions > 0 ? (toCart / sessions) * 100 : 0;

  // Возвраты и отмены
  const returns   = d.returns          ?? 0;
  const cancelled = d.cancelled_units  ?? 0;
  const returnRate = ordersNow > 0 ? (returns / ordersNow) * 100 : 0;

  // Остатки — дни до out-of-stock
  const stock     = d.stock_qty     ?? 0;
  const dailySales = salesNow / 14;
  const daysLeft  = dailySales > 0 ? Math.round(stock / dailySales) : 999;

  // Маржа
  const cogs      = d.cost_price  ?? 0;
  const price     = d.price       ?? 0;
  const commission = d.commission ?? 0;
  const logistics  = d.logistics  ?? 0;
  const adSpend    = d.ad_spend   ?? 0;
  const margin     = price > 0 ? ((price - cogs - commission - logistics - adSpend) / price) * 100 : 0;

  // ДРР (доля рекламных расходов)
  const drr = salesNow > 0 ? (adSpend / salesNow) * 100 : 0;

  // Приоритет задачи
  let priority = 'low';
  if (salesDelta <= -20 || ordersDelta <= -20 || daysLeft < 7) priority = 'high';
  else if (salesDelta >= 15 || ordersDelta >= 15) priority = 'medium_grow';
  else if (drr > 25 || returnRate > 15) priority = 'medium_problem';
  else if (convToCart < 3) priority = 'medium_card';

  return {
    json: {
      sku:          d.sku ?? d.article,
      name:         d.name ?? d.product_name ?? 'Без названия',
      salesNow:     Math.round(salesNow),
      salesDelta:   Math.round(salesDelta),
      ordersNow,
      ordersDelta:  Math.round(ordersDelta),
      convToCart:   Math.round(convToCart * 10) / 10,
      returnRate:   Math.round(returnRate * 10) / 10,
      daysLeft,
      stock,
      margin:       Math.round(margin),
      drr:          Math.round(drr),
      adSpend,
      price,
      priority
    }
  };
});

// Парсинг ответа Claude
const raw = $input.first().json;
const text = raw.content?.[0]?.text ?? '{"tasks":[]}';

let parsed;
try {
  const clean = text.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = { tasks: [], error: 'parse failed', raw: text };
}

const tasks = parsed.tasks ?? [];

// Сортировка: high → medium → low
const order = { high: 0, medium: 1, low: 2 };
tasks.sort((a, b) => (order[a.priority] ?? 2) - (order[b.priority] ?? 2));

// Форматируем текст для Telegram
const priorityEmoji = { high: '🔴', medium: '🟡', low: '🟢' };
const categoryLabel = {
  restock: 'Допоставка',
  price:   'Цена / скидка',
  card:    'Карточка',
  ads:     'Реклама',
  returns: 'Возвраты',
  scale:   'Масштабирование'
};

const lines = tasks.map(t =>
  `${priorityEmoji[t.priority] ?? '⚪'} *${t.name}* [${t.sku}]\n` +
  `📌 ${categoryLabel[t.category] ?? t.category}\n` +
  `✅ ${t.action}\n` +
  `💬 ${t.reason}\n` +
  `⏰ Срок: ${t.deadline}`
).join('\n\n');

const telegramText = `📊 *Задачи по Ozon на сегодня* (${new Date().toLocaleDateString('ru-RU')})\n\n${lines || 'Нет срочных задач — всё в норме ✅'}`;

return [{
  json: {
    tasks,
    telegramText,
    totalTasks: tasks.length,
    highCount:  tasks.filter(t => t.priority === 'high').length
  }
}];
